import sys
import requests
import re
from urllib.parse import urlparse
from time import sleep

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def sanitize_label(label):
    return re.sub(r'[^a-zA-Z0-9_-]', '', label)

def probe_url(label, url):
    if not is_valid_url(url):
        return "Invalid URL format"
    try:
        headers = {'User-Agent': 'CustomProbe/1.0'}
        response = requests.get(url, timeout=5, headers=headers, verify=True)
        return str(response.status_code)
    except requests.exceptions.RequestException as e:
        return f"Request failed: {type(e).__name__}"

for line in sys.stdin:
    label, url = line.strip().split(' ', 1)
    label = sanitize_label(label)
    result = probe_url(label, url)
    print(f"{label} {result}")
    with open('probe.log', 'a') as log_file:
        log_file.write(f"{label} {result}\n")
    sleep(0.1)  # Basic rate limiting
